41			{"severity six", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":6},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
42			{"severity string", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":"3"},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
43			{"severity fractional", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":2.5},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
44			{"enabled string", `{"id":"v","rules":{"sandwich":{"enabled":"yes","severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
45			{"multiplier one", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":1}}}`},
