50			{"sandwich with multiplier", `{"id":"v","rules":{"sandwich":{"enabled":true,"severity":3,"multiplier":2},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`},
51		}
52		for _, tc := range bad {
53			t.Run(tc.name, func(t *testing.T) {
54				if _, err := ParseRuleVersion([]byte(tc.spec)); err == nil {
55					t.Fatal("expected error")
