63		if v.ID != "strict" || !v.Rules.Sandwich.Enabled || v.Rules.Sandwich.Severity != 5 ||
64			!v.Rules.Displacement.Enabled || v.Rules.Displacement.Severity != 4 || v.Rules.Displacement.Multiplier != 5 {
65			t.Fatalf("parsed version wrong: %+v", v)
