565		if err != nil {
566			t.Fatal(err)
567		}
568		if reports[0].Findings == nil || len(reports[0].Findings) != 0 {
569			t.Fatalf("both rules off must yield an empty findings array: %+v", reports[0].Findings)
570		}
571	}
572	
573	func TestReplayMultiplierOverflowSafe(t *testing.T) {
574		dir := t.TempDir()
575		spec := `{"id":"big","rules":{"sandwich":{"enabled":false,"severity":1},"displacement":{"enabled":true,"severity":2,"multiplier":100}}}`
576		register(t, dir, spec)
577		input := fmt.Sprintf(`{"chainId":"1","blockHash":"0xov","blockNumber":1,"swaps":[{"TxHash":"0xf1","Pool":"p","Trader":"a","In":0,"Out":0,"GasPrice":%[1]d,"Index":0},{"TxHash":"0xv1","Pool":"p","Trader":"b","In":0,"Out":0,"GasPrice":%[1]d,"Index":1},{"TxHash":"0xf2","Pool":"q","Trader":"a","In":0,"Out":0,"GasPrice":%[1]d,"Index":2},{"TxHash":"0xv2","Pool":"q","Trader":"b","In":0,"Out":0,"GasPrice":100000000000000000,"Index":3}]}`, math.MaxInt64)
578		reports, err := ReplayWithVersion(strings.NewReader(input), dir, "big")
579		if err != nil {
580			t.Fatal(err)
581		}
582		got := map[string]string{}
583		for _, f := range reports[0].Findings {
584			got[f.TxHash] = f.Kind
585		}
586		// victim MaxInt64: 100x would overflow, must not flag.
587		if _, flagged := got["0xv1"]; flagged {
588			t.Fatal("0xv1 must not be flagged (overflow)")
589		}
590		// victim 1e17, front MaxInt64 ~ 92x: not strictly above 100x, must not flag.
591		if _, flagged := got["0xv2"]; flagged {
592			t.Fatal("0xv2 must not be flagged (92x < 100x)")
593		}
594	}
