596	func TestReimportReturnsOriginalReportAfterVersionChange(t *testing.T) {
597		dir := t.TempDir()
598		first := replay(t, dir, sandwichInput)
599		if first[0].Version.ID != BuiltinVersionID {
600			t.Fatalf("default replay must use builtin, got %+v", first[0].Version)
601		}
602		register(t, dir, strictSpec)
603		if _, err := EnableVersion(dir, "strict"); err != nil {
604			t.Fatal(err)
605		}
606		second := replay(t, dir, sandwichInput)
607		if second[0].Version.ID != BuiltinVersionID {
608			t.Fatalf("reimport must return the original report, got version %+v", second[0].Version)
609		}
610		if len(second[0].Findings) != 1 || second[0].Findings[0].Severity != 3 {
611			t.Fatalf("reimport findings changed: %+v", second[0].Findings)
612		}
613		data, err := readArchive(dir)
614		if err != nil {
615			t.Fatal(err)
616		}
617		if len(data.Records) != 1 {
618			t.Fatalf("reimport added records: %d", len(data.Records))
619		}
620	}
