683	func TestCompareAddedAndSorted(t *testing.T) {
684		dir := t.TempDir()
685		// Builtin flags nothing (front gas 15 < 2*10? no: 15 > 20 false... 15 < 20, no displacement).
686		// A looser version (multiplier 1 not allowed; use severity-only change via multiplier 2 with
687		// front 25 > 20 for 0xvc, and front 21 > 20 for 0xva) — instead register a version with
688		// multiplier 2 but higher sandwich severity to also produce a change; keep it simple:
689		// builtin: no findings; strict2 (multiplier 2, but front 25/21 flagged): two added, hash-sorted.
690		input := `{"chainId":"1","blockHash":"0xadd","blockNumber":3,"swaps":[` +
691			`{"TxHash":"0xfz","Pool":"p1","Trader":"w","In":1,"Out":1,"GasPrice":25,"Index":0},` +
692			`{"TxHash":"0xvz","Pool":"p1","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":1},` +
693			`{"TxHash":"0xfa","Pool":"p2","Trader":"w","In":1,"Out":1,"GasPrice":21,"Index":2},` +
694			`{"TxHash":"0xva","Pool":"p2","Trader":"u","In":1,"Out":1,"GasPrice":10,"Index":3}]}`
695		reports := replay(t, dir, input)
696		if len(reports[0].Findings) != 2 {
697			t.Fatalf("setup: builtin should flag both (25>20, 21>20): %+v", reports[0].Findings)
698		}
699		// Compare against a version with multiplier 3: 25 > 30 false, 21 > 30 false -> both removed, sorted.
700		spec := `{"id":"x3","rules":{"sandwich":{"enabled":true,"severity":3},"displacement":{"enabled":true,"severity":2,"multiplier":3}}}`
701		register(t, dir, spec)
702		result, err := Compare(dir, "1", "0xadd", "x3")
703		if err != nil {
704			t.Fatal(err)
705		}
706		if len(result.Removed) != 2 || result.Removed[0].TxHash != "0xva" || result.Removed[1].TxHash != "0xvz" {
707			t.Fatalf("removed not sorted by tx hash: %+v", result.Removed)
708		}
709		// Reverse direction: comparing a no-finding record against builtin adds them.
710		// Use the same block under x3 archived in a second archive for the added case.
711		dir2 := t.TempDir()
712		register(t, dir2, spec)
713		if _, err := ReplayWithVersion(strings.NewReader(input), dir2, "x3"); err != nil {
714			t.Fatal(err)
715		}
716		result2, err := Compare(dir2, "1", "0xadd", BuiltinVersionID)
717		if err != nil {
718			t.Fatal(err)
719		}
720		if len(result2.Added) != 2 || result2.Added[0].TxHash != "0xva" || result2.Added[1].TxHash != "0xvz" {
721			t.Fatalf("added not sorted by tx hash: %+v", result2.Added)
722		}
723		if result2.OriginalVersion.ID != "x3" {
724			t.Fatalf("original version wrong: %+v", result2.OriginalVersion)
725		}
726	}
