296		register(t, dir, offSpec)
297		v, err := GetVersion(dir, "off")
298		if err != nil {
299			t.Fatalf("an explicitly disabled version must show: %v", err)
300		}
301		if want := mustRuleVersion(t, offSpec); v != want {
302			t.Fatalf("shown version = %+v, want %+v", v, want)
303		}
304	}
