				t.Fatalf("twin = %+v, want %+v", twin, want)
			}
			b, err := GetVersion(dir, BuiltinVersionID)
			if err != nil || b != BuiltinVersion() {
				t.Fatalf("builtin blocked by corrupt enabled sibling: %+v, %v", b, err)
