141	func TestCompareRegressionFullDiff(t *testing.T) {
142		dir := setupCompareArchive(t)
143	
144		result, err := Compare(dir, "1", "0xblk", "candC")
145		if err != nil {
146			t.Fatalf("Compare: %v", err)
147		}
148	
149		// Block identity is exactly the selected chain/block; the same-height
150		// same-chain decoy and the same-hash other-chain decoy never mix in.
151		if result.ChainID != "1" || result.BlockHash != "0xblk" || result.BlockNumber != 100 {
152			t.Fatalf("block identity wrong: %s/%s @%d", result.ChainID, result.BlockHash, result.BlockNumber)
153		}
154	
155		// Each side carries its own full parameters: the archived conclusion
156		// uses archA even though liveB is now enabled, and the candidate side
157		// uses candC rather than the enabled liveB.
158		if !reflect.DeepEqual(result.OriginalVersion, mustRuleVersion(t, archivedVersionSpec)) {
159			t.Fatalf("original version = %+v, want archA", result.OriginalVersion)
160		}
161		if !reflect.DeepEqual(result.ComparedVersion, mustRuleVersion(t, candidateVersionSpec)) {
162			t.Fatalf("compared version = %+v, want candC", result.ComparedVersion)
163		}
164		if result.ComparedVersion.ID == "liveB" ||
165			result.ComparedVersion.Rules.Sandwich.Enabled ||
166			result.ComparedVersion.Rules.Displacement.Multiplier != 2 {
167			t.Fatalf("candidate side leaked the enabled version: %+v", result.ComparedVersion)
168		}
169	
170		// Original findings: severity desc, hash asc within a severity.
171		// p1 and p5 are both sandwiches sev4 (hash asc: 0xa0v before 0xe0v),
172		// the p2 displacement sev1 comes last.
173		wantOrig := []struct {
174			tx       string
175			kind     string
176			severity int
177			evidence int
178		}{
179			{"0xa0v", "sandwich", 4, 3},
180			{"0xe0v", "sandwich", 4, 3},
181			{"0xb0v", "displacement", 1, 2},
182		}
183		if len(result.OriginalFindings) != len(wantOrig) {
184			t.Fatalf("original findings = %+v", result.OriginalFindings)
185		}
186		for i, w := range wantOrig {
187			got := result.OriginalFindings[i]
188			if got.TxHash != w.tx || got.Kind != w.kind || got.Severity != w.severity || len(got.Evidence) != w.evidence {
189				t.Fatalf("original[%d] = %+v, want %+v", i, got, w)
190			}
191		}
192	
193		// Candidate findings: all displacement sev4 under candC (sandwich is
194		// off), hash asc. In particular 0xa0v is a displacement here, so the
195		// enabled liveB (which would still flag it as a sandwich sev5) was
196		// never consulted.
197		wantComp := []struct {
198			tx       string
199			evidence int
200		}{
201			{"0xa0v", 2},
202			{"0xb0v", 2},
203			{"0xd0v", 2},
204		}
205		if len(result.ComparedFindings) != len(wantComp) {
206			t.Fatalf("compared findings = %+v", result.ComparedFindings)
207		}
208		for i, w := range wantComp {
209			got := result.ComparedFindings[i]
210			if got.TxHash != w.tx || got.Kind != "displacement" || got.Severity != 4 || len(got.Evidence) != w.evidence {
211				t.Fatalf("compared[%d] = %+v, want tx %s displacement sev4 with %d evidence", i, got, w.tx, w.evidence)
212			}
213		}
214	
215		// Diffs are per victim transaction with the expected shapes.
216		if len(result.Added) != 1 || result.Added[0].TxHash != "0xd0v" {
217			t.Fatalf("added = %+v", result.Added)
218		}
219		if len(result.Removed) != 1 || result.Removed[0].TxHash != "0xe0v" {
220			t.Fatalf("removed = %+v", result.Removed)
221		}
222		if len(result.Changed) != 2 {
223			t.Fatalf("changed = %+v", result.Changed)
224		}
225		if result.Changed[0].TxHash != "0xa0v" || result.Changed[1].TxHash != "0xb0v" {
226			t.Fatalf("changed not hash-sorted: %+v", result.Changed)
227		}
228	
229		// Sandwich -> displacement for one transaction stays a single change
230		// carrying both conclusions; it must never be split into add+remove.
231		kindChange := result.Changed[0]
232		if kindChange.Original.Kind != "sandwich" || kindChange.Original.Severity != 4 ||
233			len(kindChange.Original.Evidence) != 3 {
234			t.Fatalf("kind change original side wrong: %+v", kindChange.Original)
235		}
236		if kindChange.Compared.Kind != "displacement" || kindChange.Compared.Severity != 4 ||
237			len(kindChange.Compared.Evidence) != 2 {
238			t.Fatalf("kind change compared side wrong: %+v", kindChange.Compared)
239		}
240		// Severity-only change likewise keeps both sides.
241		sevChange := result.Changed[1]
242		if sevChange.Original.Kind != "displacement" || sevChange.Original.Severity != 1 ||
243			sevChange.Compared.Kind != "displacement" || sevChange.Compared.Severity != 4 {
244			t.Fatalf("severity change wrong: %+v", sevChange)
245		}
246	
247		// The victim flagged identically under both versions (none in this
248		// block) would be absent from every diff list; p3's swaps stay only
249		// in the full evidence record.
250	
251		// Full archived swap records survive: all 13, in Index order, with
252		// every original field, including swaps that took no part in any
253		// conclusion (the sandwich backs, 0xb0z and the whole p3 pair).
254		if len(result.Swaps) != 13 {
255			t.Fatalf("swaps = %+v", result.Swaps)
256		}
257		wantSwap := Swap{TxHash: "0xb0z", Pool: "p2", Trader: "z", In: 1, Out: 1, GasPrice: 10, Index: 5}
258		if !reflect.DeepEqual(result.Swaps[5], wantSwap) {
259			t.Fatalf("swap record not preserved: got %+v", result.Swaps[5])
260		}
261		for i, s := range result.Swaps {
262			if s.Index != i {
263				t.Fatalf("swaps not in index order at %d: %+v", i, s)
264			}
265		}
266	
267		// Evidence inside conclusions keeps raw tx/pool/trader/amount/gas/index.
268		ev := result.OriginalFindings[0].Evidence[0]
269		if ev != (Swap{TxHash: "0xa0f", Pool: "p1", Trader: "bot", In: 1, Out: 1, GasPrice: 90, Index: 0}) {
270			t.Fatalf("sandwich evidence damaged: %+v", ev)
271		}
272	}
