624	
625	// corruptVersionCases is the full matrix of ways a stored candidate
626	// version document can stop satisfying the registration rules: missing,
627	// null, wrong-typed or out-of-range fields on either rule (including a
628	// rule explicitly disabled), and missing rule/rules objects. Both the
629	// single-block comparison and the review-range evaluation must refuse the
630	// whole operation with ErrCorruptVersion for every one of them.
631	var corruptVersionCases = []struct {
632		name    string
633		mutate  func(t *testing.T, ver map[string]any)
634		wantErr string
635	}{
636		{"multiplier missing", func(t *testing.T, v map[string]any) {
637			delete(storedRule(t, v, "displacement"), "multiplier")
638		}, "multiplier"},
639		{"multiplier zero", func(t *testing.T, v map[string]any) {
640			storedRule(t, v, "displacement")["multiplier"] = 0
641		}, "multiplier"},
642		{"multiplier below range", func(t *testing.T, v map[string]any) {
643			storedRule(t, v, "displacement")["multiplier"] = 1
644		}, "multiplier"},
645		{"multiplier above range", func(t *testing.T, v map[string]any) {
646			storedRule(t, v, "displacement")["multiplier"] = 101
647		}, "multiplier"},
648		{"multiplier null", func(t *testing.T, v map[string]any) {
649			storedRule(t, v, "displacement")["multiplier"] = nil
650		}, "multiplier"},
651		{"multiplier wrong type", func(t *testing.T, v map[string]any) {
652			storedRule(t, v, "displacement")["multiplier"] = "2"
653		}, "multiplier"},
654		{"displacement severity missing", func(t *testing.T, v map[string]any) {
655			delete(storedRule(t, v, "displacement"), "severity")
656		}, "severity"},
657		{"displacement severity zero", func(t *testing.T, v map[string]any) {
658			storedRule(t, v, "displacement")["severity"] = 0
659		}, "severity"},
660		{"displacement severity above range", func(t *testing.T, v map[string]any) {
661			storedRule(t, v, "displacement")["severity"] = 6
662		}, "severity"},
663		{"displacement severity null", func(t *testing.T, v map[string]any) {
664			storedRule(t, v, "displacement")["severity"] = nil
665		}, "severity"},
666		{"displacement enabled missing", func(t *testing.T, v map[string]any) {
667			delete(storedRule(t, v, "displacement"), "enabled")
668		}, "enabled"},
669		{"displacement enabled null", func(t *testing.T, v map[string]any) {
670			storedRule(t, v, "displacement")["enabled"] = nil
671		}, "enabled"},
672		{"displacement enabled wrong type", func(t *testing.T, v map[string]any) {
673			storedRule(t, v, "displacement")["enabled"] = "true"
674		}, "enabled"},
675		// The sandwich rule is disabled in candC, but a disabled rule must
676		// still declare complete, in-range parameters; an explicit false is a
677		// legal off state and stays valid.
678		{"disabled sandwich severity zero", func(t *testing.T, v map[string]any) {
679			storedRule(t, v, "sandwich")["severity"] = 0
680		}, "severity"},
681		{"disabled sandwich enabled missing", func(t *testing.T, v map[string]any) {
682			delete(storedRule(t, v, "sandwich"), "enabled")
683		}, "enabled"},
684		{"sandwich object missing", func(t *testing.T, v map[string]any) {
685			delete(v["rules"].(map[string]any), "sandwich")
686		}, "sandwich"},
687		{"displacement object missing", func(t *testing.T, v map[string]any) {
688			delete(v["rules"].(map[string]any), "displacement")
689		}, "displacement"},
690		{"sandwich object null", func(t *testing.T, v map[string]any) {
691			v["rules"].(map[string]any)["sandwich"] = nil
692		}, "sandwich"},
693		{"rules object missing", func(t *testing.T, v map[string]any) {
694			delete(v, "rules")
695		}, "rules"},
696		{"rules null", func(t *testing.T, v map[string]any) {
697			v["rules"] = nil
698		}, "rules"},
699		// Unknown fields are rejected at registration, so a stored document
700		// that grew one is corrupt too.
701		{"unknown field", func(t *testing.T, v map[string]any) {
702			v["extra"] = 1
703		}, "extra"},
704		{"unknown rule", func(t *testing.T, v map[string]any) {
705			v["rules"].(map[string]any)["frontrun"] = map[string]any{"enabled": true, "severity": 1}
706		}, "frontrun"},
707	}
708	
709	func TestCompareCorruptVersionRefused(t *testing.T) {
710		for _, tc := range corruptVersionCases {
711			t.Run(tc.name, func(t *testing.T) {
712				dir := setupCorruptCompareArchive(t)
713				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
714					tc.mutate(t, ver)
715				})
716				_, err := Compare(dir, "1", "0xblk", "candC")
717				if err == nil {
718					t.Fatalf("corrupt version compared successfully")
719				}
720				if !errors.Is(err, ErrCorruptVersion) {
721					t.Fatalf("error = %v, want ErrCorruptVersion", err)
722				}
723				if errors.Is(err, ErrUnknownVersion) || errors.Is(err, ErrUnknownBlock) {
724					t.Fatalf("corruption misreported as unknown version/block: %v", err)
725				}
726				if !strings.Contains(err.Error(), "candC") {
727					t.Fatalf("error must name the requested version, got %v", err)
728				}
729				if !strings.Contains(err.Error(), tc.wantErr) {
730					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
731				}
732			})
733		}
734	}
735	
736	func TestCompareCorruptVersionEmptySwapsStillRefused(t *testing.T) {
737		dir := t.TempDir()
738		register(t, dir, candidateVersionSpec)
739		// A block with no swaps produces no conclusions under any version; the
740		// corrupt candidate must still be refused, not reported as an empty
741		// success.
742		input := `{"chainId":"1","blockHash":"0xempty","blockNumber":3,"swaps":[]}`
743		if _, err := ReplayWithVersion(strings.NewReader(input), dir, "candC"); err != nil {
744			t.Fatal(err)
745		}
746		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
747			delete(storedRule(t, ver, "displacement"), "multiplier")
748		})
749		_, err := Compare(dir, "1", "0xempty", "candC")
750		if !errors.Is(err, ErrCorruptVersion) {
751			t.Fatalf("error = %v, want ErrCorruptVersion", err)
752		}
753	}
754	
755	func TestCompareCorruptVersionDistinctFromUnknown(t *testing.T) {
756		dir := setupCorruptCompareArchive(t)
757		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
758			delete(storedRule(t, ver, "displacement"), "multiplier")
759		})
760	
761		// A version that was never registered stays an unknown-version
762		// failure, never a corruption one.
763		if _, err := Compare(dir, "1", "0xblk", "ghost"); !errors.Is(err, ErrUnknownVersion) ||
764			errors.Is(err, ErrCorruptVersion) {
765			t.Fatalf("unknown version error = %v", err)
766		}
767		// An unknown block stays an unknown-block failure.
768		if _, err := Compare(dir, "1", "0xghost", "candC"); !errors.Is(err, ErrUnknownBlock) {
769			t.Fatalf("unknown block error = %v", err)
770		}
771		// The corrupt sibling does not contaminate intact versions: comparing
772		// under twin or builtin still succeeds against the same archive.
773		for _, id := range []string{"twin", BuiltinVersionID} {
774			result, err := Compare(dir, "1", "0xblk", id)
775			if err != nil {
776				t.Fatalf("compare under intact %s failed: %v", id, err)
777			}
778			if len(result.ComparedFindings) != 1 || result.ComparedFindings[0].Kind != "displacement" {
779				t.Fatalf("compare under intact %s misjudged: %+v", id, result.ComparedFindings)
780			}
781		}
782	}
783	
784	func TestCompareCorruptVersionReadOnly(t *testing.T) {
785		dir := setupCorruptCompareArchive(t)
786		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
787			storedRule(t, ver, "displacement")["multiplier"] = 0
788		})
789		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
790		if err != nil {
791			t.Fatal(err)
792		}
793		if _, err := Compare(dir, "1", "0xblk", "candC"); !errors.Is(err, ErrCorruptVersion) {
794			t.Fatalf("error = %v, want ErrCorruptVersion", err)
795		}
796		after, err := os.ReadFile(filepath.Join(dir, archiveFileName))
797		if err != nil {
798			t.Fatal(err)
799		}
800		if !reflect.DeepEqual(before, after) {
801			t.Fatalf("failed compare against a corrupt version changed the archive")
802		}
803		// The archived report keeps its candC conclusions and parameters.
804		report, err := Query(dir, "1", "0xblk")
805		if err != nil {
806			t.Fatal(err)
807		}
808		if report.Version.ID != "candC" || len(report.Findings) != 1 ||
809			report.Findings[0].Kind != "displacement" || report.Findings[0].Severity != 4 {
810			t.Fatalf("archived report changed: %+v", report)
811		}
812	}
