func TestCompareRegressionIdenticalConclusionsHaveEmptyDiff(t *testing.T) {
	dir := t.TempDir()
	replay(t, dir, sandwichInput) // archived under builtin
	register(t, dir, twinVersionSpec)
	result, err := Compare(dir, "1", "0xa", "twin")
	if err != nil {
