107	// against re-registration of the corrupt version's own ID: a legal
108	// resubmission must fail with ErrCorruptVersion naming the version and the
109	// offending rule or field — never created:false, never ErrVersionConflict —
110	// and must leave the stored declaration untouched.
111	func TestRegisterCorruptExistingIDRefused(t *testing.T) {
