176	// a repeated field — damage registration could never have produced — is
177	// preserved byte for byte when another version registers, and is judged
178	// corrupt (never unknown, never conflicting) when its own ID is resubmitted.
179	func TestRegisterCorruptDuplicateFieldSibling(t *testing.T) {
180		dir := setupCorruptCompareArchive(t)
181		path := filepath.Join(dir, archiveFileName)
182		text := string(readArchiveFile(t, dir))
183		vsec := strings.Index(text, `"versions":`)
184		if vsec < 0 {
185			t.Fatal("versions section not found in archive")
186		}
187		at := strings.Index(text[vsec:], `"id": "candC"`)
188		if at < 0 {
189			t.Fatal("candC entry not found in versions section")
190		}
191		at += vsec
192		anchor := `"severity": 4,`
193		field := strings.Index(text[at:], anchor)
194		if field < 0 {
195			t.Fatal("candC severity field not found")
196		}
197		pos := at + field
198		patched := text[:pos] + `"severity": 4, ` + text[pos:]
199		if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
200			t.Fatal(err)
201		}
202		// Normalize the hand-patched file through the same raw-version document
203		// shape registration rewrites, so the byte comparison below is not
204		// defeated by the patch's own whitespace; the duplicate field itself
205		// survives the round trip because versions stay raw stored documents.
206		normalized, err := json.MarshalIndent(mustReplayDoc(t, path), "", "  ")
207		if err != nil {
208			t.Fatal(err)
209		}
210		if err := os.WriteFile(path, normalized, 0o644); err != nil {
211			t.Fatal(err)
212		}
213		before := readEnableSkeleton(t, dir)
214	
215		// A legal new registration succeeds and leaves the duplicate-field
216		// document exactly as stored.
217		if _, created, err := RegisterVersion(dir, []byte(freshVersionSpec)); err != nil || !created {
218			t.Fatalf("registering past a duplicate-field sibling: created=%v err=%v", created, err)
219		}
220		after := readEnableSkeleton(t, dir)
221		if !reflect.DeepEqual(before.Versions, after.Versions[:len(before.Versions)]) {
222			t.Fatalf("duplicate-field declaration changed on registration")
223		}
224	
225		// Resubmitting its own ID reports the corruption, naming the field.
226		_, _, rerr := RegisterVersion(dir, []byte(candidateVersionSpec))
227		if !errors.Is(rerr, ErrCorruptVersion) || !errors.Is(rerr, ErrDuplicateField) {
228			t.Fatalf("duplicate-field resubmission: err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", rerr)
229		}
230		if !strings.Contains(rerr.Error(), "candC") || !strings.Contains(rerr.Error(), "severity") {
231			t.Fatalf("error must name candC and severity, got %v", rerr)
232		}
233	}
234	
235	// TestRegisterAppendsAfterExistingVersions pins the ordering guarantee: a
236	// new version lands after every existing one, and an intact existing ID
237	// keeps its established outcomes — identical parameters return created:false
238	// and different parameters report ErrVersionConflict, neither rewriting the
239	// archive.
240	func TestRegisterAppendsAfterExistingVersions(t *testing.T) {
241		dir := setupCorruptCompareArchive(t)
242		before := readArchiveFile(t, dir)
243	
244		if _, created, err := RegisterVersion(dir, []byte(freshVersionSpec)); err != nil || !created {
245			t.Fatalf("register fresh: created=%v err=%v", created, err)
246		}
247		versions, _, err := ListVersions(dir)
248		if err != nil {
249			t.Fatal(err)
250		}
251		if len(versions) != 4 || versions[1].ID != "candC" || versions[2].ID != "twin" || versions[3].ID != "fresh" {
252			t.Fatalf("version order = %+v, want builtin, candC, twin, fresh", versions)
253		}
254	
255		// Intact existing ID: identical parameters are a no-op success.
256		if v, created, err := RegisterVersion(dir, []byte(candidateVersionSpec)); err != nil || created ||
257			v != mustRuleVersion(t, candidateVersionSpec) {
258			t.Fatalf("identical retry: v=%+v created=%v err=%v", v, created, err)
259		}
260		// Intact existing ID: different parameters are a conflict.
261		conflicting := `{"id":"candC","rules":{"sandwich":{"enabled":true,"severity":1},"displacement":{"enabled":true,"severity":2,"multiplier":2}}}`
262		if _, _, err := RegisterVersion(dir, []byte(conflicting)); !errors.Is(err, ErrVersionConflict) ||
263			errors.Is(err, ErrCorruptVersion) {
264			t.Fatalf("different parameters: err = %v, want ErrVersionConflict", err)
265		}
266		// Neither the retry nor the conflict rewrote anything but the one append.
267		after := readEnableSkeleton(t, dir)
268		if len(after.Versions) != 3 {
269			t.Fatalf("version count changed by retry/conflict: %d", len(after.Versions))
270		}
271		var beforeSkel enableSkeleton
272		if err := json.Unmarshal(before, &beforeSkel); err != nil {
273			t.Fatal(err)
274		}
275		if !reflect.DeepEqual(beforeSkel.Versions, after.Versions[:len(beforeSkel.Versions)]) {
276			t.Fatalf("existing declarations changed by retry/conflict")
277		}
278	}
279	
280	// TestRegisterPreservesAllPriorState builds an archive holding every kind of
281	// state, then registers a new version and proves only the versions section
282	// grew: the enabled marker, historical reports, suppressions, alert
283	// processing records and manual reviews are all untouched.
284	func TestRegisterPreservesAllPriorState(t *testing.T) {
285		dir := t.TempDir()
286		register(t, dir, candidateVersionSpec)
287		if _, err := ReplayWithVersion(strings.NewReader(sandwichInput), dir, "candC"); err != nil {
288			t.Fatal(err)
289		}
290		if _, err := EnableVersion(dir, "candC"); err != nil {
291			t.Fatal(err)
292		}
293		if _, _, err := RegisterSuppression(dir, []byte(
294			`{"id":"s1","chainId":"1","pool":"p1","kind":"displacement","channel":"ops","startHeight":1,"endHeight":100,"reason":"r"}`,
295		)); err != nil {
296			t.Fatal(err)
297		}
298		if _, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1); err != nil {
299			t.Fatal(err)
300		}
301		if _, err := SubmitReview(dir, ReviewSubmission{
302			ChainID: "1", BlockHash: "0xa", TxHash: "0xvictim", Kind: "displacement",
303			SubmissionID: "rev-1", Operator: "alice", Reason: "looks fine",
304			Status: ReviewStatusFalsePositive, ExpectedVersion: 0,
305		}); err != nil {
306			t.Fatal(err)
307		}
308		before := readEnableSkeleton(t, dir)
309	
310		if _, created, err := RegisterVersion(dir, []byte(freshVersionSpec)); err != nil || !created {
311			t.Fatalf("register fresh: created=%v err=%v", created, err)
312		}
313	
314		after := readEnableSkeleton(t, dir)
315		if !reflect.DeepEqual(before.Versions, after.Versions[:len(before.Versions)]) {
316			t.Fatalf("existing declarations changed on registration")
317		}
318		if after.EnabledVersion != "candC" {
319			t.Fatalf("enabled marker changed on registration: %q", after.EnabledVersion)
320		}
321		if !reflect.DeepEqual(before.Records, after.Records) {
322			t.Fatalf("historical reports changed on registration")
323		}
324		if !reflect.DeepEqual(before.Suppressions, after.Suppressions) {
325			t.Fatalf("suppressions changed on registration")
326		}
327		if !reflect.DeepEqual(before.AlertRecords, after.AlertRecords) {
328			t.Fatalf("alert records changed on registration")
329		}
330		if !reflect.DeepEqual(before.Reviews, after.Reviews) {
331			t.Fatalf("manual reviews changed on registration")
332		}
333	}
334	
335	// TestRegisterInvalidArchiveReported covers the environment-level failures:
336	// an archive whose whole file is not valid JSON must error clearly and be
337	// left alone — no partial registration.
338	func TestRegisterInvalidArchiveReported(t *testing.T) {
339		dir := t.TempDir()
340		register(t, dir, candidateVersionSpec)
341		path := filepath.Join(dir, archiveFileName)
342		if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
343			t.Fatal(err)
344		}
345		before := readArchiveFile(t, dir)
346		if _, _, err := RegisterVersion(dir, []byte(freshVersionSpec)); err == nil ||
347			errors.Is(err, ErrCorruptVersion) || errors.Is(err, ErrVersionConflict) {
348			t.Fatalf("invalid-JSON archive error = %v, want a whole-archive corruption error", err)
349		}
350		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
351			t.Fatalf("failed registration rewrote an invalid archive")
352		}
353	}
